def commonFactors(a: int, b: int) -> int:
    # Compute the greatest common divisor
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)
    count = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            count += 1   # i is a divisor
            if i != g // i:
                count += 1   # g // i is also a divisor, if different
        i += 1
    return count
